answer = []
for index, source in enumerate(sources):
    obj = {name: source[name] for name in ('code_id', 'source_id', 'source_sha256', 'number')}
    obj['proposed_xml'] = (ROOT / files[index]).read_text().strip()
    obj.update(editorial[index])
    obj['status'] = 'rewrite_draft'
    obj['change_type'] = 'normative_reduction'
    obj['reform_policy_id'] = 'editorial_direction_2026_10_19'
    key = source['code_id'] + '|' + source['source_id']
    obj['reference_checks'] = []
    for target_key in references['requirements'][key]:
        target = references['targets'][target_key]
        obj['reference_checks'].append({
            'target_key': target_key,
            'view_sha256': target['view_sha256'],
            'assessment': assessments[index][target['number']],
        })
    answer.append(obj)

(ROOT / 'answer.json').write_text(json.dumps(answer, ensure_ascii=False, indent=2) + '\n')
